package com.dbsync.dialect.db2;

import com.dbsync.common.model.ColumnMeta;
import com.dbsync.common.model.TableMeta;
import com.dbsync.common.options.TriggerOptions;
import com.dbsync.dialect.TriggerDdlGenerator;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.stream.Collectors;

/**
 * DB2 LUW 触发器日志 DDL 生成器。
 *
 * <p>DB2 的三个特殊点（架构 §5.3）：
 * <ol>
 *   <li>必须 {@code REFERENCING NEW AS N}（或 {@code OLD AS O}）声明行别名，否则无法引用列；</li>
 *   <li>必须 {@code MODE DB2SQL}（复合语句）；单条 INSERT 不需要 {@code BEGIN...END}；</li>
 *   <li>日志表主键用 {@code GENERATED ALWAYS AS IDENTITY}，但显式写入 seq 时需
 *       {@code OVERRIDING SYSTEM VALUE}，因此这里改用 {@code BY DEFAULT}。</li>
 * </ol>
 */
public final class Db2TriggerDdlGenerator implements TriggerDdlGenerator {

    private static final int MAX_IDENTIFIER = 128;

    @Override
    public String changeLogTableName(String baseTable) {
        String suffix = "_SYNC_LOG";
        if (baseTable.length() + suffix.length() <= MAX_IDENTIFIER) {
            return baseTable + suffix;
        }
        return baseTable.substring(0, Math.max(1, MAX_IDENTIFIER - suffix.length())) + suffix;
    }

    @Override
    public List<String> createChangeLogTableDdl(TableMeta t, TriggerOptions opts) {
        String log = quote(changeLogTableName(t.getTableName()));
        String ddl = "CREATE TABLE " + log + " ("
                + "\"ID\" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY, "
                + "\"OP\" VARCHAR(8) NOT NULL, "
                + "\"PK_JSON\" VARCHAR(2048) NOT NULL, "
                + "\"BEFORE_JSON\" CLOB(1M) NULL, "
                + "\"AFTER_JSON\" CLOB(1M) NULL, "
                + "\"COMMIT_TS\" TIMESTAMP(3) NOT NULL, "
                + "PRIMARY KEY (\"ID\"))";
        String idx = "CREATE INDEX " + quote(changeLogTableName(t.getTableName()) + "_TS_IDX")
                + " ON " + log + " (\"COMMIT_TS\")";
        return List.of(ddl, idx);
    }

    @Override
    public List<String> createTriggerDdl(TableMeta t, TriggerOptions opts) {
        TriggerOptions options = opts == null ? TriggerOptions.defaults() : opts;
        String table = quote(t.getTableName());
        String log = quote(changeLogTableName(t.getTableName()));
        List<String> ddl = new ArrayList<>();

        ddl.add("CREATE TRIGGER " + quote(triggerName(t, "AI")) + " AFTER INSERT ON " + table
                + " REFERENCING NEW AS N FOR EACH ROW MODE DB2SQL INSERT INTO " + log
                + " (\"OP\",\"PK_JSON\",\"AFTER_JSON\",\"COMMIT_TS\") VALUES ('INSERT', "
                + pkJsonExpression(t, "N") + ", " + jsonObjectExpression(t, "N")
                + ", CURRENT TIMESTAMP)");

        ddl.add("CREATE TRIGGER " + quote(triggerName(t, "AU")) + " AFTER UPDATE ON " + table
                + " REFERENCING NEW AS N OLD AS O FOR EACH ROW MODE DB2SQL INSERT INTO " + log
                + " (\"OP\",\"PK_JSON\",\"BEFORE_JSON\",\"AFTER_JSON\",\"COMMIT_TS\") VALUES ('UPDATE', "
                + pkJsonExpression(t, "N") + ", "
                + (options.isIncludeBeforeImage() ? jsonObjectExpression(t, "O") : "NULL") + ", "
                + jsonObjectExpression(t, "N") + ", CURRENT TIMESTAMP)");

        ddl.add("CREATE TRIGGER " + quote(triggerName(t, "AD")) + " AFTER DELETE ON " + table
                + " REFERENCING OLD AS O FOR EACH ROW MODE DB2SQL INSERT INTO " + log
                + " (\"OP\",\"PK_JSON\",\"BEFORE_JSON\",\"COMMIT_TS\") VALUES ('DELETE', "
                + pkJsonExpression(t, "O") + ", " + jsonObjectExpression(t, "O")
                + ", CURRENT TIMESTAMP)");
        return List.copyOf(ddl);
    }

    @Override
    public List<String> dropTriggerDdl(TableMeta t, TriggerOptions opts) {
        List<String> ddl = new ArrayList<>();
        ddl.add("DROP TRIGGER " + quote(triggerName(t, "AI")));
        ddl.add("DROP TRIGGER " + quote(triggerName(t, "AU")));
        ddl.add("DROP TRIGGER " + quote(triggerName(t, "AD")));
        TriggerOptions options = opts == null ? TriggerOptions.defaults() : opts;
        if (options.isDropLogTableOnUninstall()) {
            ddl.add("DROP TABLE " + quote(changeLogTableName(t.getTableName())));
        }
        return List.copyOf(ddl);
    }

    @Override
    public String pollSql(String quotedLogTable, long lastLogId, int batchSize) {
        int limit = batchSize <= 0 ? 500 : Math.min(batchSize, 5000);
        return "SELECT \"ID\",\"OP\",\"PK_JSON\",\"BEFORE_JSON\",\"AFTER_JSON\",\"COMMIT_TS\" FROM "
                + quotedLogTable + " WHERE \"ID\" > " + lastLogId + " ORDER BY \"ID\" FETCH FIRST "
                + limit + " ROWS ONLY";
    }

    private String triggerName(TableMeta t, String action) {
        String name = t.getTableName() + "_SN_" + action;
        return name.length() <= MAX_IDENTIFIER ? name : name.substring(0, MAX_IDENTIFIER);
    }

    private String pkJsonExpression(TableMeta t, String alias) {
        List<String> cols = t.primaryKeyNames().isEmpty()
                ? List.of(t.getColumns().get(0).getName()) : t.primaryKeyNames();
        return "JSON_ARRAY(" + cols.stream().map(c -> alias + "." + quote(c))
                .collect(Collectors.joining(", ")) + ")";
    }

    private String jsonObjectExpression(TableMeta t, String alias) {
        List<String> parts = new ArrayList<>();
        for (ColumnMeta c : t.getColumns()) {
            parts.add("'" + c.getName().toUpperCase(Locale.ROOT) + "'");
            parts.add(alias + "." + quote(c.getName()));
        }
        return "JSON_OBJECT(" + String.join(", ", parts) + ")";
    }

    private String quote(String id) {
        return "\"" + id.replace("\"", "\"\"") + "\"";
    }
}
